import { type ConfigPlugin, withPodfile } from 'expo/config-plugins';

/**
 * Raises every Pods target to the app's own iOS deployment target.
 *
 * Xcode 27 refuses to build anything targeting below iOS 15.0. React Native's
 * `react_native_post_install` already lifts each pod target to its minimum,
 * but not the resource bundles those pods ship alongside them
 * (`AppAuth-AppAuthCore_Privacy`, `ReachabilitySwift-ReachabilitySwift`, ...),
 * which keep whatever their podspec declared - often 12.0.
 *
 * `ios/` is generated by `expo prebuild` and gitignored, so the fix has to
 * live here to survive `--clean`. Nothing in the app runs below its own
 * deployment target, so raising a pod to it never changes what ships.
 */

const MARKER = '# @generated with-ios-pod-deployment-target';

const POST_INSTALL = /^( *)post_install do \|installer\|\n/m;

const hook = (indent: string) =>
  [
    MARKER,
    'app_deployment_target = installer.aggregate_targets.map { |t| t.platform.deployment_target }.max',
    'installer.pods_project.targets.each do |target|',
    '  target.build_configurations.each do |build_configuration|',
    "    current = build_configuration.build_settings['IPHONEOS_DEPLOYMENT_TARGET']",
    '    next if current.nil? || Pod::Version.new(current) >= app_deployment_target',
    "    build_configuration.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = app_deployment_target.to_s",
    '  end',
    'end',
    '',
  ]
    .map((line) => (line ? `${indent}${line}` : line))
    .join('\n');

const withIosPodDeploymentTarget: ConfigPlugin = (config) =>
  withPodfile(config, (config) => {
    const podfile = config.modResults.contents;
    if (podfile.includes(MARKER)) return config;

    // Failing loudly beats a Podfile that silently stops building on Xcode 27
    // the next time the Expo template changes shape.
    const match = POST_INSTALL.exec(podfile);
    if (!match) {
      throw new Error(
        'with-ios-pod-deployment-target: no `post_install do |installer|` block in the Podfile',
      );
    }

    const bodyIndent = `${match[1]}  `;
    config.modResults.contents = podfile.replace(POST_INSTALL, (line) => line + hook(bodyIndent));
    return config;
  });

export default withIosPodDeploymentTarget;
